def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        expired_keys = [key for key, (value, write_time) in cache.items() if write_time + ttl <= t]
        for key in expired_keys:
            del cache[key]

        if op[0] == 'put':
            key, value = op[2], op[3]

            # If key exists, remove it first
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU (first item)
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry (most recently used)
            cache[key] = (value, t)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

